#include <stdint.h>
#include <string.h>
#include "../drivers/Inc/spi_driver.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif


// Command codes
#define COMMAND_LED_CTRL      		0x50
#define COMMAND_SENSOR_READ      	0x51
#define COMMAND_LED_READ      		0x52
#define COMMAND_PRINT      			0x53
#define COMMAND_ID_READ      		0x54

#define LED_ON     1
#define LED_OFF    0

// Arduino analog pins
#define ANALOG_PIN0 	0
#define ANALOG_PIN1 	1
#define ANALOG_PIN2 	2
#define ANALOG_PIN3 	3
#define ANALOG_PIN4 	4

// Arduino LED
#define LED_PIN  13

void delay(void) {
	for (uint32_t i=0; i<500000/2;i++);
}

void SPI2_GPIOInits(void) {
	/*
	 * This function initializes the GPIO pins for SPI2:
	 * SPI2_NSS  -> PB12
	   SPI2_SCK  -> PB13
	   SPI2_MISO -> PB14
	   SPI2_MOSI -> PB15
	   Alternate Function Mode -> 5
	 * */

	// Enable the GPIOB peripheral clock
	volatile uint32_t *pRCC_AHB1ENR = (volatile uint32_t*) (0x40023800 + 0x30);
	*pRCC_AHB1ENR |= (1 << 1);

	// Setting the Pin Modes to ALTERNATE FUNCTION (bits 24-31 -> PB12 to PB15)
	volatile uint32_t *pGPIOB_MODER = (volatile uint32_t*) (0x40020400 + 0x00);
	*pGPIOB_MODER &= ~(0xFF000000);
	*pGPIOB_MODER |= (0xAA000000);

	// Configure Output Type to Push-Pull (bits 12-15)
	volatile uint32_t *pGPIOB_OTYPER = (volatile uint32_t*) (0x40020400 + 0x04);
	*pGPIOB_OTYPER &= ~(0x0000F000); // Bit clear = 0 (Push-Pull for PB12-PB15)

	// Configuring speed to High Speed
	volatile uint32_t *pGPIOB_OSPEEDR = (volatile uint32_t*) (0x40020400 + 0x08);
	*pGPIOB_OSPEEDR &= ~(0xFF000000);
	*pGPIOB_OSPEEDR |= (0xAA000000);

	// Configure Pull-Up / Pull-Down to No PUPD (bits 24-31)
	volatile uint32_t *pGPIOB_PUPDR = (volatile uint32_t*) (0x40020400 + 0x0C);
	*pGPIOB_PUPDR &= ~(0xFF000000); // Bit clear = 00 (No Pull-Up, No Pull-Down)

	// Configuring AFRH for PB12-PB15 (AFRH12-AFRH15)
	volatile uint32_t *pGPIOB_AFRH = (volatile uint32_t*) (0x40020400 + 0x24);
	*pGPIOB_AFRH &= ~(0xFFFF0000);
	*pGPIOB_AFRH |= (0x55550000);
}

void SPI2_Inits(void) {
	/*
	 * This function initializes the SPI2 peripheral's params
	 * */

	SPI_Handle_t SPI2handle;

	SPI2handle.pSPIx = SPI2;
	SPI2handle.SPI_Config.SPI_BusConfig = SPI_BUS_CONFIG_FD;
	SPI2handle.SPI_Config.SPI_DeviceMode = SPI_DEVICE_MODE_MASTER;
	SPI2handle.SPI_Config.SPI_SclkSpeed = SPI_SCLK_SPEED_DIV8;//generates sclk of 2MHz
	SPI2handle.SPI_Config.SPI_DFF = SPI_DFF_8BITS;
	SPI2handle.SPI_Config.SPI_CPOL = SPI_CPOL_LOW;
	SPI2handle.SPI_Config.SPI_CPHA = SPI_CPHA_LOW;
	SPI2handle.SPI_Config.SPI_SSM = SPI_SSM_DI; //hardwareS slave management enabled for NSS pin

	SPI_Init(&SPI2handle);
}

void GPIO_ButtonInit(void) {
	/*
	 * This function initializes PA0 as an Input pin for the push button:
	 * PA0 -> Button Input
	 * Mode -> Input (00)
	 * Speed -> Fast Speed (10)
	 * Pull-Up/Pull-Down -> No PUPD (00)
	 */

	// Enable the GPIOA peripheral clock (bit 0 of RCC_AHB1ENR)
	volatile uint32_t *pRCC_AHB1ENR = (volatile uint32_t*) (0x40023800 + 0x30);
	*pRCC_AHB1ENR |= (1 << 0);

	// Setting Pin Mode to INPUT for PA0 (bits 0-1)
	volatile uint32_t *pGPIOA_MODER = (volatile uint32_t*) (0x40020000 + 0x00);
	*pGPIOA_MODER &= ~(0x00000003); // Bit clear = 00 (Input mode)

	// Configuring speed to Fast Speed for PA0 (bits 0-1 -> 10)
	volatile uint32_t *pGPIOA_OSPEEDR = (volatile uint32_t*) (0x40020000 + 0x08);
	*pGPIOA_OSPEEDR &= ~(0x00000003);
	*pGPIOA_OSPEEDR |= (0x00000002); // 10 = Fast Speed

	// Configure Pull-Up / Pull-Down to No PUPD for PA0 (bits 0-1)
	volatile uint32_t *pGPIOA_PUPDR = (volatile uint32_t*) (0x40020000 + 0x0C);
	*pGPIOA_PUPDR &= ~(0x00000003); // Bit clear = 00 (No Pull-Up, No Pull-Down)
}

uint8_t GPIO_ReadFromInputPin(uint8_t PinNumber) {
	volatile uint32_t *pGPIOA_IDR = (volatile uint32_t*) (0x40020000 + 0x10);
	return (uint8_t) ((*pGPIOA_IDR >> PinNumber) & 0x1);
}

uint8_t SPI_VerifyResponse(uint8_t ack_byte) {
	if (ack_byte == 0xF5) {
		// ack
		return 1;
	} else {
		// nack
		return 0;
	}
}


int main(void)
{
	char user_data[] = "Hello World!";
	uint8_t dummy_write = 0xff;
	uint8_t dummy_read;

	GPIO_ButtonInit();

	// SPI_GPIOInits() function initializes the GPIO pins to behave as SPI2 pins
	SPI2_GPIOInits();

	SPI_PeriClockControl(SPI2, ENABLE);

	// THis function initializes the SPI2 peripheral params
	SPI2_Inits();

	// SPI_SSIConfig(SPI2, ENABLE);
	SPI_SSOEConfig(SPI2, ENABLE);

	while (1) {
		while (!GPIO_ReadFromInputPin(0)); // if LOW i.e not pressed, keep hanging here

		delay();

		// Enable the SPI2 peripheral
		SPI_PeripheralControl(SPI2, ENABLE);

		// COMMAND 1: CMD_LED_CTRL
		uint8_t command_code = COMMAND_LED_CTRL;
		uint8_t ack_byte;
		uint8_t args[2];

		SPI_SendData(SPI2, &command_code, 1);

		// Performing a dummy read to clear the RXNE flag
		SPI_ReceiveData(SPI2, &dummy_read, 1);
		// To receive ACK from slave's shift register, we must send some dummy data (1 byte)
		SPI_SendData(SPI2, &dummy_write, 1);
		// Receiving the ACK byte received from Arduino slave
		SPI_ReceiveData(SPI2, &ack_byte, 1);

		static uint8_t led_state = 0;
		// Checking if the ACK byte is valid or not
		if (SPI_VerifyResponse(ack_byte)) {
			led_state ^= 0x01; // previous led_state XOR 1 --> for toggling LED
			// Send arguments to slave
			args[0] = LED_PIN;
			args[1] = led_state;
			//send arguments
			SPI_SendData(SPI2,args,2);
			// dummy read
			SPI_ReceiveData(SPI2,args,2);
		}

		//Checking if SPI is not busy before closing communication
		while (SPI_GetFlagStatus(SPI2, SPI_BUSY_FLAG));

		SPI_PeripheralControl(SPI2, DISABLE);
	}

    return 0;
}

